insert into archive_private.catalog_entries(kind,entry_id,document) values('concert','20211017','{"id":20211017,"date":"2021-10-17","year":2021,"time":"","title":"在風裡，擁抱彼此的夢｜逢甲校友管樂團十週年","place":"衛武營國家藝術文化中心・音樂廳","ens":"逢甲大學校友管樂團、逢甲大學管樂團","cond":"呂彥慶","host":"","asset":"lu-early","source":"https://www.npac-weiwuying.org/programs/60ae0db8881c640008b38ab9","sourceName":"衛武營節目資料","story":"校友與在校生跨世代同台，與薩克斯風演奏家王裕文合作。逢甲大學的演後報導記錄了這場因疫情延期後成行的十週年公演。","rows":[{"zh":"瑰寶之石","composer":"","arr":"","orig":"","src":"web","source":"https://www.npac-weiwuying.org/programs/60ae0db8881c640008b38ab9"},{"zh":"為中音薩克斯風所作的狂想曲","composer":"André Waignein","arr":"","orig":"","src":"web","source":"https://www.npac-weiwuying.org/programs/60ae0db8881c640008b38ab9"},{"zh":"水手與海洋之歌","composer":"","arr":"","orig":"","src":"web","source":"https://www.npac-weiwuying.org/programs/60ae0db8881c640008b38ab9"},{"zh":"第六幸福客棧","composer":"","arr":"","orig":"","src":"web","source":"https://www.npac-weiwuying.org/programs/60ae0db8881c640008b38ab9"},{"zh":"神隱少女電影選粹","composer":"","arr":"","orig":"","src":"web","source":"https://www.npac-weiwuying.org/programs/60ae0db8881c640008b38ab9"},{"zh":"卡門歌劇選粹","composer":"Georges Bizet","arr":"","orig":"","src":"web","source":"https://www.npac-weiwuying.org/programs/60ae0db8881c640008b38ab9"}],"media":[],"photos":0,"prog":false,"sample":false,"need":false,"imageLabel":"呂彥慶指揮資料照｜逢甲校友管樂團","rowsNote":"依場館最終公告列六首。7/6 校友平台宣傳另列《交響詩「台灣」》《致我的戰友》，與最終公告不同，未合併為已演曲目。原訂 7/2，延期至 10/17。","sources":["https://www.npac-weiwuying.org/programs/60ae0db8881c640008b38ab9","https://www.cna.com.tw/postwrite/chi/302039","https://mm.fcuaa.com.tw/newsDetail-2-0504-246688.html"],"timelineOrder":20211017}'::jsonb) on conflict do nothing;
